  log('upload.failure',path=str(local.resolve()),reason='HTTP 503 temporary');failure=True;break
 state['uploaded']+=1;url='https://github.com/user-attachments/assets/fixture-'+str(state['uploaded']);state['assets'][url]=str(local.resolve());log('upload.success',path=str(local.resolve()),url=url);uploaded+=1
