if operation=='create':
 state['pr']={'url':'https://github.com/fixture/design/pull/51','title':flag('--title'),'body':body,'isDraft':'--draft' in args,'headRefOid':'b'*40,'headRefName':'feature/dialog','headRepository':{'nameWithOwner':'fixture/design'},'baseRefName':'main','state':'OPEN'}
else:
 if flag('--title') is not None:state['pr']['title']=flag('--title')
 if not attachments or uploaded>0:state['pr']['body']=body
log('pr.'+operation,args=args,body=state['pr']['body'],draft=state['pr']['isDraft']);save();print(state['pr']['url'])
